def check_m(m):
    """
    Checks if there exist two non-empty disjoint subsets X, Y of {1, ..., m}
    such that sum(X) = sum(Y) = m(m+1)/6.
    """
    if m <= 0:
        return False

    # Calculate the target sum T
    total_sum_m = m * (m + 1) / 2

    # The required sum T must be an integer and non-zero
    if total_sum_m % 3 != 0:
        return False

    T = int(total_sum_m / 3)

    if T == 0:
        # Since X and Y must be non-empty, T must be positive for m >= 1
        return False 

    S = list(range(1, m + 1))

    # Iterate through all possible non-empty subsets X of S
    # We iterate using bitmasks from 1 up to 2^m - 1

    found_m = False

    for i in range(1, 1 << m):
        X = []
        sum_X = 0
        for j in range(m):
            if (i >> j) & 1:
                element = S[j]
                X.append(element)
                sum_X += element

        if sum_X == T:
            # We found a potential X. Now check if a suitable Y exists in R = S \ X

            R = []
            for j in range(m):
                if not ((i >> j) & 1): # If element S[j] is not in X
                    R.append(S[j])

            # Check if there is a non-empty subset Y of R summing to T
            # This is a standard subset sum problem on R.

            if not R:
                continue # Should not happen if T > 0, as X must be a proper subset of S for Y to exist

            R_size = len(R)
            Y_found = False

            # Iterate through all non-empty subsets Y of R
            for k in range(1, 1 << R_size):
                sum_Y = 0
                for l in range(R_size):
                    if (k >> l) & 1:
                        sum_Y += R[l]

                if sum_Y == T:
                    Y_found = True
                    break

            if Y_found:
                found_m = True
                break # Found a pair (X, Y) for this m

    return found_m

# Run verification for m = 1 to 20
results = {}
for m in range(1, 21):
    results[m] = check_m(m)

print("m | Check Result")
print("-" * 20)
for m, result in results.items():
    print(f"{m:2} | {result}")

